    {
        var baseRate = tier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
